import time
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import Adafruit_ADS1x15
import pigpio
import numpy as np
import math
import signal
import sys

# Constants
ADC_MAX_VALUE = 1647  # ADS1015 max value for 3.3V range
PWM_FREQUENCY = 500  # PWM frequency in Hz
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
ADC_GAIN = 1
ADC_CHANNEL = 0
ADC_ADDRESS = 0x48  # Default I2C address for ADS1015
MOTOR_MAX_PWM = 255

# Global Variables
pwm_duty_cycle = 0.0
adc = None
pi = None
accelerometer = None
magnetometer = None
i2c = None

class MotorController:
    """Controls a stepper motor via pigpio."""

    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.microstep_resolution = "Full"  # Default
        self.direction = "CCW"  # Default

        try:
            self.pi = pigpio.pi()
            if not self.pi.connected:
                raise Exception("pigpio daemon not running")
            self.pi.set_mode(self.dir_pin, pigpio.OUTPUT)
            self.pi.set_mode(self.step_pin, pigpio.OUTPUT)
            self.pi.set_mode(self.ms0_pin, pigpio.OUTPUT)
            self.pi.set_mode(self.ms1_pin, pigpio.OUTPUT)
            self.set_microstep_resolution(self.microstep_resolution)
            self.set_direction(self.direction)
        except Exception as e:
            raise MotorControllerInitializationError(f"Failed to initialize motor controller: {e}")

    def set_microstep_resolution(self, resolution):
        """Sets the microstep resolution."""
        resolution_settings = {
            "Full": (0, 0),
            "Half": (1, 0),
            "1/4": (0, 1),
            "1/8": (1, 1),
        }
        try:
            ms0, ms1 = resolution_settings[resolution]
            self.pi.write(self.ms0_pin, ms0)
            self.pi.write(self.ms1_pin, ms1)
            self.microstep_resolution = resolution
        except KeyError:
            raise ValueError("Invalid microstep resolution")
        except Exception as e:
            raise MotorControlError(f"Failed to set microstep resolution: {e}")

    def set_direction(self, direction):
        """Sets the motor direction."""
        direction_settings = {
            "CW": 1,
            "CCW": 0,
        }
        try:
            dir_value = direction_settings[direction]
            self.pi.write(self.dir_pin, dir_value)
            self.direction = direction
        except KeyError:
            raise ValueError("Invalid direction")
        except Exception as e:
            raise MotorControlError(f"Failed to set motor direction: {e}")

    def set_pwm_duty_cycle(self, duty_cycle):
        """Sets the PWM duty cycle for motor speed control."""
        global pwm_duty_cycle
        try:
            duty_cycle = max(0, min(duty_cycle, MOTOR_MAX_PWM))  # Clamp to valid range
            self.pi.set_PWM_dutycycle(self.step_pin, int(duty_cycle))
            self.pi.set_PWM_frequency(self.step_pin, PWM_FREQUENCY)
            pwm_duty_cycle = duty_cycle
        except Exception as e:
            raise MotorControlError(f"Failed to set PWM duty cycle: {e}")

    def stop(self):
        """Stops the motor."""
        try:
            self.pi.set_PWM_dutycycle(self.step_pin, 0)
        except Exception as e:
            raise MotorControlError(f"Failed to stop motor: {e}")

    def cleanup(self):
        """Releases pigpio resources."""
        try:
            self.pi.stop()
        except Exception as e:
            print(f"Error during motor cleanup: {e}")


class SensorManager:
    """Manages accelerometer and magnetometer readings."""

    def __init__(self, i2c):
        global accelerometer, magnetometer
        try:
            accelerometer = adafruit_lsm303_accel.LSM303_Accel(i2c)
            magnetometer = adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
        except Exception as e:
            raise SensorInitializationError(f"Failed to initialize sensors: {e}")

    def get_acceleration(self):
        """Returns accelerometer data as a tuple (x, y, z)."""
        try:
            return accelerometer.acceleration
        except Exception as e:
            raise SensorReadError(f"Failed to read acceleration: {e}")

    def get_inclination(self):
        """Returns inclination angles (XZ, YZ)."""
        try:
            return accelerometer.inclination
        except Exception as e:
            raise SensorReadError(f"Failed to read inclination: {e}")

    def get_magnetic_field(self):
        """Returns magnetometer data as a tuple (x, y, z)."""
        try:
            return magnetometer.magnetic
        except Exception as e:
            raise SensorReadError(f"Failed to read magnetic field: {e}")

    def get_heading(self):
        """Calculates and returns the heading in degrees."""
        try:
            mag_x, mag_y, _ = self.get_magnetic_field()
            angle = math.atan2(mag_y, mag_x)
            heading = math.degrees(angle)
            return heading if heading >= 0 else heading + 360
        except Exception as e:
            raise SensorReadError(f"Failed to calculate heading: {e}")


class ADCManager:
    """Manages ADC readings and voltage conversion."""

    def __init__(self, address=ADC_ADDRESS, busnum=None, gain=ADC_GAIN):
        global adc
        try:
            adc = Adafruit_ADS1x15.ADS1015(address=address, busnum=busnum)
        except Exception as e:
            raise ADCInitializationError(f"Failed to initialize ADC: {e}")

    def read_channel(self, channel):
        """Reads the raw ADC value from the specified channel."""
        try:
            return adc.read_adc(channel, gain=ADC_GAIN)
        except Exception as e:
            raise ADCReadError(f"Failed to read ADC channel {channel}: {e}")

    def read_voltage(self, channel):
        """Converts the raw ADC value to a voltage."""
        try:
            raw_value = self.read_channel(channel)
            # Convert raw value to voltage
            voltage = (raw_value * 3.3) / ADC_MAX_VALUE
            return voltage
        except Exception as e:
            raise ADCReadError(f"Failed to read voltage from channel {channel}: {e}")


# Custom Exception Classes
class MotorControllerInitializationError(Exception):
    pass


class SensorInitializationError(Exception):
    pass


class ADCInitializationError(Exception):
    pass


class MotorControlError(Exception):
    pass


class SensorReadError(Exception):
    pass


class ADCReadError(Exception):
    pass


# --- Helper Functions ---
def initialize_i2c():
    """Initializes the I2C bus."""
    global i2c
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        raise I2CInitializationError(f"Failed to initialize I2C: {e}")


class I2CInitializationError(Exception):
    pass


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    print("\nExiting program...")
    global motor, sensor_manager, adc_manager, pi, i2c

    if motor:
        try:
            motor.stop()
            motor.cleanup()
        except Exception as e:
            print(f"Error stopping motor: {e}")
    if adc_manager:
        try:
            pass  # No specific cleanup needed for ADCManager
        except Exception as e:
            print(f"Error cleaning up ADC: {e}")
    if pi:
        try:
            pigpio.stop(pi)
        except Exception as e:
            print(f"Error stopping pigpio: {e}")
    if i2c:
        try:
            i2c.deinit()
        except Exception as e:
            print(f"Error deinitializing I2C: {e}")

    sys.exit(0)


def map_adc_to_pwm(adc_value):
    """Maps ADC value (0-ADC_MAX_VALUE) to PWM duty cycle (0-255)."""
    return int((adc_value / ADC_MAX_VALUE) * MOTOR_MAX_PWM)


# --- Main Program ---
if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        # Initialize hardware
        initialize_i2c()
        motor = MotorController(MOTOR_DIR_PIN, MOTOR_STEP_PIN, MOTOR_MS0_PIN, MOTOR_MS1_PIN)
        sensor_manager = SensorManager(i2c)
        adc_manager = ADCManager()

        # Set initial motor parameters
        motor.set_microstep_resolution("1/8")
        motor.set_direction("CCW")

        while True:
            try:
                # Read ADC channel 0
                adc_value = adc_manager.read_channel(ADC_CHANNEL)

                # Map ADC value to PWM duty cycle
                pwm_duty_cycle = map_adc_to_pwm(adc_value)

                # Set motor speed
                motor.set_pwm_duty_cycle(pwm_duty_cycle)

                # Read sensor data
                acc_x, acc_y, acc_z = sensor_manager.get_acceleration()
                inclination_xz, inclination_yz = sensor_manager.get_inclination()
                mag_x, mag_y, mag_z = sensor_manager.get_magnetic_field()
                heading = sensor_manager.get_heading()

                # Print sensor data
                print("Acceleration (m/s^2):", acc_x, acc_y, acc_z)
                print("Inclination (degrees):", inclination_xz, inclination_yz)
                print("Magnetic Field (gauss):", mag_x, mag_y, mag_z)
                print("Heading (degrees):", heading)
                print("-" * 20)

                time.sleep(1)

            except (
                ADCReadError,
                MotorControlError,
                SensorReadError,
            ) as e:
                print(f"Error during main loop: {e}")
                time.sleep(1)  # Wait before retrying

    except (
        I2CInitializationError,
        SensorInitializationError,
        ADCInitializationError,
        MotorControllerInitializationError,
    ) as e:
        print(f"Fatal error: {e}")
        sys.exit(1)

