import smbus2 as smbus
import time

# Constants
VDD = 5.0  # Fixed 5V supply from Raspberry Pi to ADS1115
VOLTAGE_DIVIDER_R1 = 2000  # Resistance of R1 in ohms
VOLTAGE_DIVIDER_R2 = 1000  # Resistance of R2 in ohms
MAX_BATTERY_VOLTAGE = 13.8  # Fully charged battery voltage
MIN_BATTERY_VOLTAGE = 10.5  # Minimum battery voltage
ADS1115_ADDRESS = 0x48  # I2C address of ADS1115
HYSTERESIS_THRESHOLD = 1  # Percentage change threshold for update
I2C_BUS_NUMBER = 1 # I2C bus number on Raspberry Pi

# Initialize I2C bus and last percentage
try:
    bus = smbus.SMBus(I2C_BUS_NUMBER)
    last_percentage = None
except Exception as e:
    print(f"Error initializing I2C: {e}")
    exit(1)


def configure_ads1115(channel=0):
    """Configures the ADS1115 to read from a specified channel."""
    config = {
        0: [0x83, 0xE0],  # A0
    }.get(channel, None)
    if config is None:
        raise ValueError("Invalid ADS1115 channel")
    try:
        bus.write_i2c_block_data(ADS1115_ADDRESS, 0x01, config)
    except OSError as e:
        raise OSError(f"Error configuring ADS1115: {e}")


def read_raw_ads1115():
    """Reads raw data from the ADS1115."""
    try:
        data = bus.read_i2c_block_data(ADS1115_ADDRESS, 0x00, 2)
        raw_data = (data[0] << 8) | data[1]
        if raw_data > 32767:
            raw_data -= 65536
        return raw_data
    except OSError as e:
        raise OSError(f"Error reading ADS1115: {e}")


def convert_to_battery_voltage(raw_data):
    """Converts raw ADS1115 data to battery voltage."""
    measured_voltage = (raw_data / 32767.0) * 6.144  # +/- 6.144V range
    battery_voltage = measured_voltage * (VOLTAGE_DIVIDER_R1 + VOLTAGE_DIVIDER_R2) / VOLTAGE_DIVIDER_R2
    return battery_voltage

def calculate_battery_percentage(battery_voltage):
    """Calculates battery percentage based on voltage."""
    percentage = ((battery_voltage - MIN_BATTERY_VOLTAGE) / (MAX_BATTERY_VOLTAGE - MIN_BATTERY_VOLTAGE)) * 100
    return max(0, min(100, percentage))



def main():
    """Main function to read and display battery information."""
    global last_percentage
    try:
        while True:
            configure_ads1115(0)
            time.sleep(0.1)  # Wait for conversion

            try:
                raw_data = read_raw_ads1115()
                battery_voltage = convert_to_battery_voltage(raw_data)
                percentage = calculate_battery_percentage(battery_voltage)

                if last_percentage is None or abs(percentage - last_percentage) >= HYSTERESIS_THRESHOLD:
                    print(f"Battery Voltage: {battery_voltage:.2f} V | Charge: {percentage:.2f}%")
                    last_percentage = percentage

                time.sleep(1)

            except OSError as e:
                print(f"Error during reading: {e}")
                time.sleep(1)  # Wait before retrying

    except KeyboardInterrupt:
        print("\nExiting")
    finally:
        bus.close() # Close the I2C bus


if __name__ == "__main__":
    main()

