import argparse
import datetime
import io
import os
import signal
import sys
import threading
import time
import subprocess
from picamera2 import Picamera2
import numpy as np

# Global variables for graceful shutdown
running = True
camera_lock = threading.Lock()

def signal_handler(sig, frame):
    """Handles SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    print("Shutting down gracefully...")
    running = False

def discover_cameras():
    """Discovers connected camera sensors using libcamera or v4l2-ctl."""
    cameras = []
    try:
        # Attempt to list cameras using libcamera
        result = subprocess.run(['libcamera-still', '--list-cameras'], capture_output=True, text=True, check=True)
        camera_info = result.stdout
        for line in camera_info.splitlines():
            if "Camera" in line:
                camera_id = line.split(":")[0].split(" ")[1]
                cameras.append(f"/dev/video{camera_id}")
    except FileNotFoundError:
        print("libcamera-still not found, falling back to v4l2-ctl")
        # Fallback to v4l2-ctl if libcamera-still is not available
        try:
            result = subprocess.run(['v4l2-ctl', '--list-devices'], capture_output=True, text=True, check=True)
            camera_info = result.stdout
            for line in camera_info.splitlines():
                if "Video" in line:
                    camera_path = line.split(":")[0].strip()
                    # Exclude USB webcams based on device path
                    if "usb" not in camera_path.lower():
                        cameras.append(camera_path)
        except FileNotFoundError:
            print("v4l2-ctl not found. Camera discovery failed.")
        except subprocess.CalledProcessError as e:
            print(f"Error running v4l2-ctl: {e}")
    except subprocess.CalledProcessError as e:
        print(f"Error running libcamera-still: {e}")

    return cameras

def initialize_camera(camera_id, camera_number):
    """Initializes a Picamera2 object for the given camera ID."""
    try:
        picam2 = Picamera2(camera_num=camera_number)
        config = picam2.create_still_configuration(main={"size": (640, 480)}, controls={"FrameRate": 24})
        picam2.configure(config)
        picam2.start()
        print(f"Camera {camera_number} initialized successfully.")
        return picam2
    except Exception as e:
        print(f"Error initializing camera {camera_number}: {e}")
        return None

def capture_baseline_frame(picam2):
    """Captures a baseline frame from the given Picamera2 object."""
    try:
        frame = picam2.capture_array()
        return frame
    except Exception as e:
        print(f"Error capturing baseline frame: {e}")
        return None

def detect_motion(current_frame, baseline_frame, motion_threshold, pixel_threshold):
    """Detects motion between the current frame and the baseline frame."""
    try:
        # Convert to grayscale using luminance weights
        gray_current = np.dot(current_frame[...,:3], [0.299, 0.587, 0.114]).astype(np.uint8)
        gray_baseline = np.dot(baseline_frame[...,:3], [0.299, 0.587, 0.114]).astype(np.uint8)

        # Calculate the absolute difference
        diff = np.abs(gray_current - gray_baseline)

        # Threshold the difference
        thresholded = diff > motion_threshold

        # Count the number of pixels above the threshold
        motion_pixels = np.sum(thresholded)

        # Check if motion is detected
        if motion_pixels > pixel_threshold:
            return True
        else:
            return False
    except Exception as e:
        print(f"Error detecting motion: {e}")
        return False

def record_video(picam2, video_dir, camera_number, record_duration):
    """Records video for the specified duration."""
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(video_dir, f"Camera{camera_number}_{timestamp}.h264")
        with camera_lock: # Protect file system access
            picam2.start_and_record_video(filename, record_duration)
            print(f"Recording video to {filename}")
    except Exception as e:
        print(f"Error recording video: {e}")

def main():
    """Main function to run the security camera system."""
    parser = argparse.ArgumentParser(description="Raspberry Pi Security Camera System")
    parser.add_argument("--video_dir", required=True, help="Directory to save video files")
    parser.add_argument("--motion_threshold", type=int, default=25, help="Motion detection threshold")
    parser.add_argument("--pixel_threshold", type=int, default=1000, help="Minimum number of pixels exceeding the threshold")
    parser.add_argument("--record_duration", type=int, default=10, help="Video recording duration in seconds")

    args = parser.parse_args()

    # Create the video directory if it doesn't exist
    if not os.path.exists(args.video_dir):
        try:
            os.makedirs(args.video_dir)
        except OSError as e:
            print(f"Error creating video directory: {e}")
            sys.exit(1)

    # Discover cameras
    camera_ids = discover_cameras()
    if not camera_ids:
        print("No cameras found. Exiting.")
        sys.exit(1)

    # Initialize cameras
    cameras = []
    picamera2_objects = []
    for i, camera_id in enumerate(camera_ids):
        picam2 = initialize_camera(camera_id, i)
        if picam2:
            picamera2_objects.append(picam2)
            cameras.append({"id": camera_id, "number": i, "picam2": picam2, "baseline_frame": None})
        else:
            print(f"Failed to initialize camera {i}. Skipping.")

    # Capture baseline frames
    for camera in cameras:
        baseline_frame = capture_baseline_frame(camera["picam2"])
        if baseline_frame is not None:
            camera["baseline_frame"] = baseline_frame
        else:
            print(f"Failed to capture baseline frame for camera {camera['number']}. Motion detection will not be reliable.")

    # Main loop
    try:
        while running:
            for camera in cameras:
                if camera["picam2"] and camera["baseline_frame"]:
                    try:
                        current_frame = camera["picam2"].capture_array()
                        if current_frame is not None:
                            motion_detected = detect_motion(current_frame, camera["baseline_frame"], args.motion_threshold, args.pixel_threshold)
                            if motion_detected:
                                print(f"Motion detected by Camera {camera['number']}")
                                record_video(camera["picam2"], args.video_dir, camera["number"], args.record_duration)
                                # Update baseline frame after motion is detected
                                camera["baseline_frame"] = current_frame
                        else:
                            print(f"Failed to capture frame from Camera {camera['number']}")
                    except Exception as e:
                        print(f"Error processing camera {camera['number']}: {e}")
            time.sleep(0.1)  # Reduce CPU usage
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # Release camera resources
        for camera in cameras:
            if camera["picam2"]:
                try:
                    camera["picam2"].stop()
                    camera["picam2"].close()
                except Exception as e:
                    print(f"Error releasing camera {camera['number']}: {e}")
        print("Camera resources released. Exiting.")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    main()

