from __future__ import print_function
import atexit
import threading
import time
import logging
import signal
from typing import Tuple, Optional

from flask import Flask, render_template, Response, request

from camera import Camera
from config import Config
from mail_config import send_email

# Configure logging
logging.basicConfig(filename='app.log', level=logging.ERROR, 
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize Flask app
app = Flask(__name__)

# Global lock for thread safety
execution_lock = threading.Lock()

# Configuration and camera initialization
try:
    config = Config()
    camera = Camera(config)
except Exception as e:
    logging.critical(f"Initialization failed: {e}")
    exit(1)  # Exit with error code


def detect_object_with_motion_detection() -> Tuple[bytes, bool]:
    """Detects objects using motion detection and sends email notifications if configured."""
    frame = camera.get_object_with_basic_motion_detection()
    if frame is None:
        return b'', False
    jpeg_bytes = b''.join(frame)
    if config.send_email_notifications:
        try:
            send_email(jpeg_bytes, config)
        except Exception as e:
            logging.error(f"Error sending email: {e}")
    return jpeg_bytes, True


def detect_object_with_yolo() -> Tuple[bytes, bool]:
    """Detects objects using YOLO and sends email notifications if configured."""
    frame = camera.get_object(config.classifier)
    if frame is None:
        return b'', False
    jpeg_bytes = b''.join(frame)
    if config.send_email_notifications:
        try:
            send_email(jpeg_bytes, config)
        except Exception as e:
            logging.error(f"Error sending email: {e}")
    return jpeg_bytes, True


def detect_object() -> Optional[Response]:
    """Detects objects based on configuration and returns a JPEG response."""
    with execution_lock:
        if config.classifier_name == 'motion_detector':
            jpeg_bytes, found = detect_object_with_motion_detection()
        else:
            jpeg_bytes, found = detect_object_with_yolo()

    if found:
        return Response(jpeg_bytes, mimetype='image/jpeg')
    return None


def detect_loop() -> None:
    """Continuously detects objects and sends notifications."""
    while True:
        try:
            if config.send_email_notifications and config.live_preview:
                detected_frame = detect_object()
                if detected_frame:
                    print("Object detected, sending email...")
            else:
                time.sleep(1)  # Check less frequently if notifications are off
        except Exception as e:
            logging.error(f"Error in detection loop: {e}")
            time.sleep(5)  # Wait before retrying


@app.route('/', methods=['GET', 'POST'])
def index() -> str:
    """Handles the web interface for configuration."""
    if request.method == 'POST':
        try:
            # Update config based on form data (similar to original code)
            # ... (Implementation for handling form data)
            config.load_from_request(request.form)  # Assuming config class has this method

            if config.live_preview:
                camera.set_classifier(config.classifier_name, config.classifier_path)
                camera.camera_init(config)
                camera.vs.start()  # Assuming vs is VideoStream object

                detection_thread = threading.Thread(target=detect_loop, daemon=True)
                detection_thread.start()

        except Exception as e:
            logging.error(f"Error processing form data: {e}")
            return render_template('index.html', error=str(e)) # Pass error to template

    return render_template('index.html', config=config) # Pass config to template



def gen(camera: Camera) -> bytes:
    """Generates video frames for streaming."""
    while True:
        try:
            if config.classifier_name == 'motion_detector':
                frame = camera.get_object_with_basic_motion_detection()
            elif config.live_preview:
                frame = camera.get_frame()
            else:
                frame = None

            if frame:
                yield (b'--frame\r\n'
                       b'Content-Type: image/jpeg\r\n\r\n' + b''.join(frame) + b'\r\n\r\n')
            else:
                time.sleep(0.1)  # Avoid busy-waiting

        except Exception as e:
            logging.error(f"Error generating video frame: {e}")
            time.sleep(1)



@app.route('/video_feed')
def video_feed() -> Response:
    """Provides the video feed."""
    return Response(gen(camera),
                    mimetype='multipart/x-mixed-replace; boundary=frame')


def stop_camera(signal, frame) -> None:
    """Stops the camera and exits."""
    print("Stopping camera...")
    camera.stop()
    exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, stop_camera)
    app.run(host='0.0.0.0', debug=False, threaded=True)

