"""
This script establishes a serial communication link with a Bluetooth device,
sending commands prefixed with 'X'. It uses a functional approach with error
handling and resource management.
"""

import serial
import time
import logging
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400
COMMAND_PREFIX = 'X'

def create_serial_connection(port, baudrate):
    """Creates a serial connection with error handling."""
    try:
        connection = serial.Serial(port, baudrate, timeout=1)  # Add timeout for better error handling
        logging.info(f"Connected to {port} at {baudrate} baud.")
        return connection
    except serial.SerialException as e:
        logging.error(f"Connection error: {e}")
        return None

def send_command(connection, command):
    """Sends a command over the serial connection."""
    try:
        full_command = (COMMAND_PREFIX + command).encode("utf-8")
        connection.write(full_command)
        logging.debug(f"Sent: {full_command.decode()}")
        return True
    except serial.SerialException as e:
        logging.error(f"Send error: {e}")
        return False

def get_user_input():
    """Gets user input from the console."""
    try:
        return input("Enter command (or 'q' to quit): ")
    except KeyboardInterrupt:
        return "q"  # Treat Ctrl+C as quit

def main_loop(connection):
    """Main program loop."""
    send = partial(send_command, connection) # Partial function for cleaner calls

    while True:
        user_input = get_user_input()
        if user_input.lower() == 'q':
            break
        if send(user_input):
            logging.info(f"Sent '{user_input}'")
        else:
            logging.error(f"Failed to send '{user_input}'")

def close_connection(connection):
    """Closes the serial connection."""
    if connection and connection.is_open:
        connection.close()
        logging.info("Connection closed.")

def main():
    """Main function to manage the application lifecycle."""
    serial_connection = create_serial_connection(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE)
    if serial_connection:
        try:
            main_loop(serial_connection)
        finally:
            close_connection(serial_connection)
    else:
        logging.error("Could not establish connection. Exiting.")


if __name__ == "__main__":
    main()

