import io
import logging
import threading
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2, MappedArray

from general import WebSocketHandler  # Assuming this module exists

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


def convert_to_opencv_frame(frame_data: bytes) -> Optional[np.ndarray]:
    """Converts JPEG frame data to an OpenCV frame."""
    try:
        data = np.frombuffer(frame_data, dtype=np.uint8)
        frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
        if frame is None:
            raise ValueError("Failed to decode JPEG data")
        return frame
    except Exception as e:
        logging.error(f"Error converting frame: {e}", exc_info=True)
        return None


def detect_motion(previous_frame: np.ndarray, current_frame: np.ndarray, detect_motion_function: Callable) -> Optional[bool]:
    """Detects motion between two frames using a provided function."""
    if previous_frame is None or current_frame is None:
        return None

    try:
        return detect_motion_function(previous_frame, current_frame)
    except Exception as e:
        logging.error(f"Error detecting motion: {e}", exc_info=True)
        return None



class CameraStreamBuffer:
    """Buffers and broadcasts camera frames over WebSocket."""

    def __init__(self, websocket_handler: WebSocketHandler):
        self.websocket_handler = websocket_handler
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()

    def write(self, data: bytes) -> None:
        """Writes frame data to buffer and broadcasts on new frame."""
        try:
            with self.lock:
                self.buffer.write(data)
                if data.startswith(b'\xff\xd8'):  # New JPEG frame
                    self.flush()
        except Exception as e:
            logging.error(f"Error writing to stream buffer: {e}", exc_info=True)

    def flush(self) -> None:
        """Flushes the buffer and broadcasts the frame."""
        with self.lock:
            frame_data = self.buffer.getvalue()
            if frame_data:
                self.websocket_handler.broadcast(frame_data)
                self.buffer.seek(0)
                self.buffer.truncate()


class MotionDetectionBuffer:
    """Buffers frames and performs motion detection."""

    def __init__(self, detect_motion_function: Callable):
        self.detect_motion_function = detect_motion_function
        self.buffer = io.BytesIO()
        self.previous_frame: Optional[np.ndarray] = None
        self.current_frame: Optional[np.ndarray] = None
        self.lock = threading.Lock()

    def write(self, data: bytes) -> None:
        """Writes frame data to buffer and processes on new frame."""
        try:
            with self.lock:
                self.buffer.write(data)
                if data.startswith(b'\xff\xd8'):  # New JPEG frame
                    self._process_frame()
        except Exception as e:
            logging.error(f"Error writing to motion buffer: {e}", exc_info=True)

    def _process_frame(self) -> None:
        """Reads, converts, and detects motion in the buffered frame."""
        try:
            with self.lock:
                self.buffer.seek(0)
                frame_data = self.buffer.read()
                self.buffer.seek(0)
                self.buffer.truncate()

                frame = convert_to_opencv_frame(frame_data)
                if frame is not None:
                    self.previous_frame = self.current_frame
                    self.current_frame = frame

                    if self.previous_frame is not None:
                        motion_detected = detect_motion(self.previous_frame, self.current_frame, self.detect_motion_function)
                        if motion_detected:
                            logging.info("Motion detected!")

        except Exception as e:
            logging.error(f"Error processing frame: {e}", exc_info=True)


    def flush(self) -> None:
        """Forces processing of any remaining frame data."""
        try:
            with self.lock:
                if self.buffer.tell() > 0:
                    self._process_frame()
        except Exception as e:
            logging.error(f"Error flushing motion buffer: {e}", exc_info=True)

