import time
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht

# Define LCD dimensions
LCD_COLUMNS = 16
LCD_ROWS = 2

# Define I2C address
LCD_ADDRESS = 0x27

# Define GPIO pin for DHT22 sensor
DHT_PIN = board.D4

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_lcd(i2c_bus):
    """Initialize the character LCD."""
    try:
        lcd_display = character_lcd.Character_LCD_I2C(i2c_bus, LCD_COLUMNS, LCD_ROWS, address=LCD_ADDRESS)
        return lcd_display
    except Exception as e:
        print(f"Error initializing LCD: {e}")
        return None

def initialize_dht_sensor(pin):
    """Initialize the DHT22 sensor."""
    try:
        dht_sensor = adafruit_dht.DHT22(pin)
        return dht_sensor
    except Exception as e:
        print(f"Error initializing DHT22 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Read temperature and humidity from the DHT22 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except RuntimeError as e:
        print(f"DHT22 read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}")
        return None, None

def display_data(lcd, temperature, humidity):
    """Display temperature and humidity on the LCD."""
    try:
        if temperature is not None and humidity is not None:
            lcd.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
        else:
            lcd.message = "Sensor Error"
    except Exception as e:
        print(f"LCD display error: {e}")

def main():
    """Main function to read sensor data and display it on the LCD."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    lcd_display = initialize_lcd(i2c_bus)
    if lcd_display is None:
        return

    dht_sensor = initialize_dht_sensor(DHT_PIN)
    if dht_sensor is None:
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(dht_sensor)
            display_data(lcd_display, temperature, humidity)
            time.sleep(2)
    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        # Clear the LCD on exit
        lcd_display.clear()

if __name__ == "__main__":
    main()

