import serial
import time
import csv
import sys

# Configuration constants for the temperature logger
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1
LOG_FILE = 'temperature_log.csv'


def celsius_to_fahrenheit(celsius):
    """Convert Celsius to Fahrenheit."""
    return celsius * 9 / 5 + 32


def log_temperature_data(serial_port, log_file):
    """Read temperature data from serial and log to CSV."""
    try:
        with open(log_file, 'a', newline='') as csvfile:
            csv_writer = csv.writer(csvfile)
            # Write header if the file is new
            if csvfile.tell() == 0:
                csv_writer.writerow(['timestamp', 'celsius', 'fahrenheit'])

            while True:
                try:
                    line = serial_port.readline().decode('ascii', errors='replace').strip()
                    if line:
                        try:
                            celsius = float(line)
                            fahrenheit = celsius_to_fahrenheit(celsius)
                            timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                            csv_writer.writerow([timestamp, celsius, fahrenheit])
                            print(f"Timestamp: {timestamp}, Celsius: {celsius}, Fahrenheit: {fahrenheit}")
                        except ValueError:
                            print(f"Warning: Invalid temperature reading: {line}", file=sys.stderr)
                except serial.SerialException as e:
                    print(f"Serial communication error: {e}", file=sys.stderr)
                    break  # Exit loop on serial error
                except Exception as e:
                    print(f"An unexpected error occurred: {e}", file=sys.stderr)
                    break  # Exit loop on unexpected error

    except FileNotFoundError:
        print(f"Error: Log file not found: {log_file}", file=sys.stderr)
    except Exception as e:
        print(f"Error opening log file: {e}", file=sys.stderr)


def main():
    """Main function to initialize serial and start logging."""
    try:
        # Initialize serial port
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f"Connected to serial port: {SERIAL_PORT}")
            log_temperature_data(ser, LOG_FILE)

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)  # Exit with error code
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        print("Exiting temperature logger.")


if __name__ == "__main__":
    main()

