import time
import board
import adafruit_dht

# Define sensor and pin
dht_sensor = adafruit_dht.DHT22(board.D22)

# Delay for sensor stabilization
time.sleep(1)

def read_dht_data():
    """Reads temperature and humidity from the DHT22 sensor with retries."""
    max_retries = 2
    for attempt in range(max_retries + 1):
        try:
            temperature = dht_sensor.temperature
            humidity = dht_sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                print(f"Attempt {attempt + 1}: Failed to read data, retrying...")
                time.sleep(0.1)  # Short delay before retry
        except RuntimeError as error:
            print(f"Attempt {attempt + 1}: RuntimeError: {error}")
            time.sleep(0.1)  # Short delay before retry
        except Exception as error:
            print(f"Attempt {attempt + 1}: Unexpected error: {error}")
            return None, None  # Return None for both values on unexpected error
    print("Error: Failed to read DHT22 after multiple retries.")
    return None, None

try:
    while True:
        temperature, humidity = read_dht_data()

        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature:.1f} °C, Humidity: {humidity:.1f} %")
        else:
            print("Error: Could not retrieve temperature and humidity.")

        time.sleep(3)

except KeyboardInterrupt:
    print("Program stopped by user.")
finally:
    dht_sensor.exit()
    print("DHT22 sensor cleaned up.")

