# Import necessary libraries
from flask import Flask, render_template_string
from gpiozero import LED
import signal
import sys

# Initialize Flask app
app = Flask(__name__)

# Define GPIO pin for the LED (BCM numbering)
LED_PIN = 17

# Initialize LED object
try:
    led = LED(LED_PIN)
except Exception as e:
    print(f"Error initializing LED: {e}")
    led = None  # Set led to None if initialization fails

# Define signal handler for graceful shutdown
def signal_handler(sig, frame):
    print("Shutting down gracefully...")
    if led:
        led.close()  # Release GPIO resources
    sys.exit(0)

# Register signal handler for SIGINT and SIGTERM
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Define routes
@app.route('/')
def index():
    """Index route: Displays the main control page."""
    if led:
        return render_template_string("""
            <h1>Control LED</h1>
            <a href="/light_on">Turn ON</a> | <a href="/light_off">Turn OFF</a>
        """)
    else:
        return "LED initialization failed. Check logs."

@app.route('/light_on')
def light_on():
    """Route to turn the LED on."""
    if led:
        try:
            led.on()
            return render_template_string("""
                <h1>LED is ON</h1>
                <a href="/">Back to Control</a>
            """)
        except Exception as e:
            print(f"Error turning LED on: {e}")
            return "Error turning LED on. Check logs."
    else:
        return "LED not initialized."

@app.route('/light_off')
def light_off():
    """Route to turn the LED off."""
    if led:
        try:
            led.off()
            return render_template_string("""
                <h1>LED is OFF</h1>
                <a href="/">Back to Control</a>
            """)
        except Exception as e:
            print(f"Error turning LED off: {e}")
            return "Error turning LED off. Check logs."
    else:
        return "LED not initialized."

# Run the app
if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=8080, debug=False)
    finally:
        if led:
            led.close() # Ensure GPIO resources are released on exit
        print("Application stopped.")

