# fingerprint_authentication_rpi.py
# A script to authenticate users using a fingerprint sensor on a Raspberry Pi 5.

import time
import board
import busio
import adafruit_fingerprint

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_fingerprint_sensor(i2c_bus):
    """Initializes the fingerprint sensor."""
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return sensor
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor: {e}")
        return None

def get_fingerprint(sensor):
    """Acquires and processes a fingerprint image."""
    print("Waiting for fingerprint...")
    while sensor.get_image() != adafruit_fingerprint.OK:
        pass

    print("Templating...")
    if sensor.image_2_tz(1) != adafruit_fingerprint.OK:
        return False

    print("Searching...")
    if sensor.finger_search() != adafruit_fingerprint.OK:
        return False

    return True

def authenticate_user(sensor):
    """Authenticates a user based on fingerprint match."""
    if get_fingerprint(sensor):
        print("Access Granted")
        print(f"ID: {sensor.finger_id}, Confidence: {sensor.confidence}")
        return True
    else:
        print("Access Denied")
        return False

def main():
    """Main function to run the fingerprint authentication loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_fingerprint_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            authenticate_user(sensor)
            time.sleep(1)

    except KeyboardInterrupt:
        print("\nExiting program.")

    finally:
        # No specific cleanup needed for I2C or the sensor object itself,
        # but including a finally block for potential future expansion.
        print("Program finished.")

if __name__ == "__main__":
    main()

