    Returns the number of available GPIO lines based on the Raspberry Pi model.
    """
    if model is None:
        get_raspi_model()
    if model and ('Pi 1 Model A' in model or 'Pi 1 Model B' in model):
        return 17
    else:
        return 26

# Function to handle GPIO events
def gpio_callback(channel):
    """
    Callback function for GPIO events.  Logs the event and updates the state.
    """
    global gpio_state, log
    try:
        index = gpio_ch.index(channel)
        new_state = GPIO.input(channel)
        if new_state != gpio_state[index]:
            gpio_state[index] = new_state
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            event = f"{timestamp} GPIO {channel}: {'HIGH' if new_state else 'LOW'}"
            log.append(event)
            if len(log) > LOG_SIZE:
                log.pop(0)
    except Exception as e:
        print(f"Error in GPIO callback: {e}")

# Function to initialize GPIO
def initialize_gpio():
    """
    Initializes the GPIO pins for event detection.
    """
    global gpio_ch, gpio_state
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        num_gpio = get_gpio_num()
        gpio_ch = [0, 1, 4, 7, 8, 9, 10, 11, 14, 15, 17, 18, 21, 22, 23, 24, 25][:num_gpio]
        gpio_state = [0] * len(gpio_ch)
        for ch in gpio_ch:
            GPIO.setup(ch, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.add_event_detect(ch, GPIO.BOTH, callback=gpio_callback, bouncetime=debounce_time)
        print(f"Monitoring GPIO pins: {gpio_ch}")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

# Signal handler for clean exit
def signal_handler(sig, frame):
    """
    Handles SIGINT and SIGTERM signals for clean exit.
    """
    print("\nExiting...")
    GPIO.cleanup()
    sys.exit(0)

# Main program
if __name__ == "__main__":
    # Parse command-line arguments
    debounce_time = DEFAULT_DEBOUNCE_TIME
    for i in range(1, len(sys.argv)):
        if sys.argv[i] == "-d" or sys.argv[i] == "--debounce":
            try:
                debounce_time = int(sys.argv[i+1])
            except (ValueError, IndexError):
                print("Invalid debounce time. Using default.")
            break

    # Get Raspberry Pi model
    get_raspi_model()
    print(f"Detected model: {model}")

    # Initialize GPIO
    initialize_gpio()

    # Set up signal handler
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Main loop
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        GPIO.cleanup()

