    touch_pad_b = Button(TOUCH_PAD_B_PIN)
    touch_pad_c = Button(TOUCH_PAD_C_PIN)
except Exception as e:
    print(f"Error initializing touch pads: {e}", file=sys.stderr)
    touch_pad_a = None
    touch_pad_b = None
    touch_pad_c = None

# Initialize discrete LEDs
try:
    discrete_led_red = LED(DISCRETE_LED_RED_PIN)
    discrete_led_green = LED(DISCRETE_LED_GREEN_PIN)
    discrete_led_blue = LED(DISCRETE_LED_BLUE_PIN)
except Exception as e:
