    """Calculates the decimal value of the binary number represented by the bit states."""
    value = 0
    for i, bit in enumerate(bit_states):
        if bit:
            value += 2**(NUM_BITS - 1 - i)
    return value


def update_display(value):
    """Updates the 7-segment display with the given value."""
    if display:
        try:
            display.print(value)
        except Exception as e:
            print(f"Error updating display: {e}", file=sys.stderr)


def update_discrete_leds(bit_states):
    """Updates the discrete LEDs based on the bit states."""
    if discrete_led_red and discrete_led_green and discrete_led_blue:
