            discrete_led_red.value = bit_states[0]
            discrete_led_green.value = bit_states[1]
            discrete_led_blue.value = bit_states[2]
        except Exception as e:
            print(f"Error updating discrete LEDs: {e}", file=sys.stderr)


def update_apa102(value, bit_states):
    """Updates the APA102 LED strip based on the value and bit states."""
    if strip:
        try:
            strip.clear_strip()
            if value == 0:
                strip.set_pixel(0, 10, 10, 10)  # Dim white
            elif value == MAX_VALUE:
                for i in range(7):
                    strip.set_pixel(i, 100, 100, 100)  # All white
            else:
                red = 100 if bit_states[0] else 0
                green = 100 if bit_states[1] else 0
                blue = 100 if bit_states[2] else 0
                strip.set_pixel(value, red, green, blue)
            strip.show_strip()
        except Exception as e:
            print(f"Error updating APA102 LED strip: {e}", file=sys.stderr)


def play_tone(value):
    """Plays a tone on the buzzer based on the value."""
    if buzzer:
        try:
            frequency = 440 * (2 ** ((MIDI_NOTE_BASE + value - 69) / 12.0))
            buzzer.play(frequency, 0.5)  # Play for 0.5 seconds
        except Exception as e:
            print(f"Error playing tone: {e}", file=sys.stderr)


def handle_touch(bit_index):
    """Handles a touch event on a touch pad, toggling the corresponding bit."""
    global bit_states
    bit_states[bit_index] = not bit_states[bit_index]  # Toggle the bit
    value = get_decimal_value(bit_states)
    update_display(value)
    update_discrete_leds(bit_states)
    update_apa102(value, bit_states)
    play_tone(value)


def cleanup():
    """Cleans up resources before exiting."""
    print("Cleaning up and exiting...")
    if display:
        try:
            display.clear()
        except Exception as e:
            print(f"Error clearing display during cleanup: {e}", file=sys.stderr)
    if discrete_led_red and discrete_led_green and discrete_led_blue:
        try:
            discrete_led_red.off()
            discrete_led_green.off()
            discrete_led_blue.off()
        except Exception as e:
            print(f"Error turning off discrete LEDs during cleanup: {e}", file=sys.stderr)
    if strip:
        try:
            strip.clear_strip()
        except Exception as e:
            print(f"Error clearing APA102 LED strip during cleanup: {e}", file=sys.stderr)
    if buzzer:
        try:
            buzzer.off()
        except Exception as e:
            print(f"Error turning off buzzer during cleanup: {e}", file=sys.stderr)
    print("Cleanup complete.")


def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    print("Signal received, exiting...")
    cleanup()
    sys.exit(0)


if __name__ == "__main__":
    # Set up signal handling
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize touch pad event handlers
    if touch_pad_a:
        touch_pad_a.when_pressed = lambda: handle_touch(0)  # Touch pad A corresponds to bit 0
    if touch_pad_b:
        touch_pad_b.when_pressed = lambda: handle_touch(1)  # Touch pad B corresponds to bit 1
    if touch_pad_c:
        touch_pad_c.when_pressed = lambda: handle_touch(2)  # Touch pad C corresponds to bit 2

    print("Binary Counter Rainbow HAT Demo started. Press Ctrl+C to exit.")

    try:
        while True:
            time.sleep(0.1)  # Keep the main thread alive
    except KeyboardInterrupt:
        # This block is technically redundant due to signal handling, but included for robustness
        print("Keyboard interrupt detected, exiting...")
        cleanup()
        sys.exit(0)

