import socket
import json
import time
import random
import signal
import sys
import serial
import smbus2
from gpiozero import LED  # Optional: for status indicators

# Constants for the wildlife tracking IoT gateway
LISTEN_HOST = "127.0.0.1"
LISTEN_PORT = 9099
GPS_SERIAL_PORT = "/dev/ttyAMA0"
GPS_I2C_ADDRESS = 0x42
MAX_COMMAND_LENGTH = 1024

# Global state for the tracking system
tracking_enabled = False
gps_connection = None
status_led = None  # Optional LED for status


def read_gps_position():
    """Reads GPS coordinates from the module or simulates them."""
    global gps_connection
    try:
        if gps_connection is not None:
            # Read a line from the GPS serial or I2C stream
            if isinstance(gps_connection, serial.Serial):
                line = gps_connection.readline().decode("ascii", errors="ignore").strip()
            else:
                line = gps_connection.read(256).decode("ascii", errors="ignore").strip()
            if line.startswith("$GPGGA"):
                parts = line.split(",")
                latitude = float(parts[2]) if parts[2] else 0.0
                longitude = float(parts[4]) if parts[4] else 0.0
                return {"lat": latitude, "lon": longitude}
        # Fall back to simulated coordinates if GPS is unavailable
        latitude = round(random.uniform(-90.0, 90.0), 6)
        longitude = round(random.uniform(-180.0, 180.0), 6)
        return {"lat": latitude, "lon": longitude}
    except Exception as gps_error:
        print(f"GPS read error: {gps_error}", file=sys.stderr)
        return {"lat": 0.0, "lon": 0.0}


def handle_command(command_text):
    """Handles a single remote control command and returns a JSON reply."""
    global tracking_enabled
    try:
        command_parts = command_text.split()
        if not command_parts:
            return json.dumps({"status": "error", "reason": "empty command"})
        command_name = command_parts[0].lower()
        if command_name == "start":
            tracking_enabled = True
            return json.dumps({"status": "ok", "action": "start"})
        if command_name == "stop":
            tracking_enabled = False
            return json.dumps({"status": "ok", "action": "stop"})
        if command_name == "report":
            position = read_gps_position()
            return json.dumps({"status": "ok", "action": "report", "lat": position["lat"], "lon": position["lon"]})
        return json.dumps({"status": "error", "reason": "unknown command"})
    except Exception as command_error:
        print(f"Command error: {command_error}", file=sys.stderr)
        return json.dumps({"status": "error", "reason": "internal error"})


def main():
    """Runs the wildlife tracking IoT gateway server."""
    global gps_connection, status_led
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        # Bind to the loopback address for the IoT gateway
        server_socket.bind((LISTEN_HOST, LISTEN_PORT))
        server_socket.listen(1)
        server_socket.settimeout(2.0)
        print("Wildlife tracking gateway listening on", LISTEN_PORT)
        # Initialize the GPS module over serial or I2C
        try:
            gps_connection = serial.Serial(GPS_SERIAL_PORT, baudrate=9600, timeout=1)
        except serial.SerialException:
            gps_connection = smbus2.SMBus(1)
        # Optional status LED to indicate the server is running
        status_led = LED(17)
        status_led.on()
        while True:
            try:
                client_connection, client_address = server_socket.accept()
                print("Accepted connection from", client_address)
                received_bytes = client_connection.recv(MAX_COMMAND_LENGTH)
                if received_bytes:
                    command_text = received_bytes.decode("utf-8").strip()
                    response_text = handle_command(command_text)
                    client_connection.sendall(response_text.encode("utf-8"))
                client_connection.close()
            except socket.timeout:
                # No incoming connection within the timeout window
                continue
            except Exception as accept_error:
                print(f"Accept error: {accept_error}", file=sys.stderr)
                break
    except Exception as setup_error:
        print(f"Setup error: {setup_error}", file=sys.stderr)
    finally:
        # Close the GPS connection and the server socket on shutdown
        if gps_connection is not None:
            gps_connection.close()
        server_socket.close()
        if status_led is not None:
            status_led.off()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal.default_int_handler)
    main()

