import gpiozero
import logging

# Configure logging for the hydroponics controller
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins for the hydroponics actuators
PUMP_PIN = 20
LIGHT_PIN = 21

# Initialize the pump and light actuators using gpiozero
try:
    pump = gpiozero.OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    light = gpiozero.OutputDevice(LIGHT_PIN, active_high=True, initial_value=False)
    logging.info("Actuators initialized successfully.")
except Exception as e:
    logging.error(f"Failed to initialize actuators: {e}")
    exit(1)

# Function to parse the intent from a natural language command
def parse_intent(command):
    """Parses a natural language command to determine the intended action."""
    command = command.lower()
    if "pump on" in command:
        return "pump_on"
    elif "pump off" in command:
        return "pump_off"
    elif "light" in command:
        return "light_toggle"
    else:
        return "unknown"

# Function to execute the parsed intent
def execute_intent(intent):
    """Executes the specified intent by controlling the hydroponics actuators."""
    try:
        if intent == "pump_on":
            pump.on()
            logging.info("Pump turned ON.")
        elif intent == "pump_off":
            pump.off()
            logging.info("Pump turned OFF.")
        elif intent == "light_toggle":
            if light.is_active:
                light.off()
                logging.info("Light turned OFF.")
            else:
                light.on()
                logging.info("Light turned ON.")
        elif intent == "unknown":
            logging.warning("Unknown command received.")
    except Exception as e:
        logging.error(f"Error executing intent: {e}")

# Main function to run the hydroponics controller
def main():
    """Main function to parse commands and control hydroponics actuators."""
    try:
        # List of test phrases to simulate natural language input
        phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]

        # Process each phrase
        for phrase in phrases:
            intent = parse_intent(phrase)
            logging.info(f"Parsed intent: {intent} from phrase: {phrase}")
            execute_intent(intent)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure actuators are turned off and resources are released
        pump.close()
        light.close()
        logging.info("Actuators closed and resources released.")

# Run the main function
if __name__ == "__main__":
    main()

