    def __init__(self, i2c_bus=DEFAULT_I2C_BUS, i2c_address=DEFAULT_I2C_ADDRESS, century=DEFAULT_CENTURY):
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self.century = century
        self._bus = None  # Initialize bus as None

    def _get_bus(self):
        """Lazily initializes and returns the I2C bus."""
        if self._bus is None:
            try:
                self._bus = smbus2.SMBus(self.i2c_bus)
            except FileNotFoundError as e:
                logging.error(f"I2C bus {self.i2c_bus} not found: {e}")
                raise
        return self._bus

    def _close_bus(self):
        """Closes the I2C bus if it's open."""
        if self._bus is not None:
            try:
                self._bus.close()
                self._bus = None
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")


    def validate_i2c_device(self):
        """Validates that the DS1338 is acknowledged on the I2C bus."""
        bus = self._get_bus()
        try:
            bus.read_byte(self.i2c_address)  # Minimum test: device acknowledges
            logging.info("DS1338 I2C device acknowledged.")
            return True
        except OSError as e:
            logging.error(f"DS1338 I2C device not responding: {e}")
            self._close_bus()
            return False


    def _read_time_register(self, register):
        """Reads and converts a time register value."""
        return bcd_to_int(read_register(self._get_bus(), self.i2c_address, register))


    def read_all(self):
        """Reads all time and date components from the RTC."""
        try:
            year = self._read_time_register(REGISTERS["year"])
            month = self._read_time_register(REGISTERS["month"])
            date = self._read_time_register(REGISTERS["date"])
            day = self._read_time_register(REGISTERS["day"])
            hours = bcd_to_int(read_register(self._get_bus(), self.i2c_address, REGISTERS["hours"]) & 0x3F)
            minutes = self._read_time_register(REGISTERS["minutes"])
            seconds = self._read_time_register(REGISTERS["seconds"])
            return year, month, date, day, hours, minutes, seconds
        except OSError:
            self._close_bus()
            return None


    def read_datetime(self, century=DEFAULT_CENTURY):
        """Reads the current time and returns a datetime object."""
        all_values = self.read_all()
        if all_values is None:
            return None
        year, month, date, _, hours, minutes, seconds = all_values
        try:
            return datetime(century * 100 + year, month, date, hours, minutes, seconds)
        except ValueError as e:
            logging.error(f"Invalid date/time data read from RTC: {e}")
            return None



    def write_all(self, seconds=None, minutes=None, hours=None, date=None, month=None, year=None):
        """Writes time and date components to the RTC."""

        if seconds is not None:
            write_register(self._get_bus(), self.i2c_address, REGISTERS["seconds"], int_to_bcd(seconds))
        if minutes is not None:
            write_register(self._get_bus(), self.i2c_address, REGISTERS["minutes"], int_to_bcd(minutes))
        if hours is not None:
             write_register(self._get_bus(), self.i2c_address, REGISTERS["hours"], int_to_bcd(hours)) # Ensure 24-hour format
        if date is not None:
            write_register(self._get_bus(), self.i2c_address, REGISTERS["date"], int_to_bcd(date))
        if month is not None:
            write_register(self._get_bus(), self.i2c_address, REGISTERS["month"], int_to_bcd(month))
        if year is not None:
            write_register(self._get_bus(), self.i2c_address, REGISTERS["year"], int_to_bcd(year % 100)) # Store only last two digits



    def display_time(self):
        """Displays the current time in a user-friendly format."""
        dt = self.read_datetime()
        if dt:
            logging.info("Current time: %s", dt.strftime("%Y-%m-%d %H:%M:%S"))


