import serial
import time
import pynmea2

# Serial port configuration for GPS module
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Log file path
LOG_FILE = 'gps_coordinates_log.txt'

def initialize_serial(port, baud, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def parse_gps_data(raw_data):
    """Parses the raw GPS data to extract latitude, longitude, and altitude."""
    try:
        msg = pynmea2.parse(raw_data)
        if msg.sentence_type == 'GPGGA' and msg.fix_quality == 1:
            latitude = msg.latitude
            longitude = msg.longitude
            altitude = msg.altitude
            return latitude, longitude, altitude
        return None, None, None
    except pynmea2.ParseError:
        return None, None, None

def log_coordinates(latitude, longitude, altitude, log_file):
    """Logs the GPS coordinates to a file with a timestamp."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(log_file, 'a') as file:
            file.write(f"{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read GPS data, parse it, and log the coordinates."""
    serial_port = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_port is None:
        return

    try:
        while True:
            try:
                raw_data = serial_port.readline().decode('ascii', errors='replace').strip()
                latitude, longitude, altitude = parse_gps_data(raw_data)

                if latitude is not None and longitude is not None and altitude is not None:
                    print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m")
                    log_coordinates(latitude, longitude, altitude, LOG_FILE)

                time.sleep(1)

            except Exception as e:
                print(f"An error occurred: {e}")
                time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program...")

    finally:
        serial_port.close()
        print("Serial port closed.")

if __name__ == "__main__":
    main()

