from flask import Flask, Response, request, jsonify, abort
import json
import time
import logging
import signal
import sys
import threading
import serial
import os

# Configure logging
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

app = Flask(__name__)

# Global variables
data_store = []
next_id = 1
serial_port = None  # Global serial port object
serial_lock = threading.Lock()  # Lock for serial port access
shutdown_flag = threading.Event()  # Event to signal shutdown

# Data Manager Class
class DataManager:
    """
    Manages the in-memory data store.
    """
    def __init__(self):
        self.data = []
        self.lock = threading.Lock()
        self.load_initial_data()

    def load_initial_data(self):
        """Loads initial data if the data store is empty."""
        with self.lock:
            if not self.data:
                self.create_item("Item 1", False)
                self.create_item("Item 2", True)

    def get_all(self):
        """Returns all items from the data store."""
        with self.lock:
            return self.data.copy()

    def get_by_id(self, item_id):
        """Returns an item by its ID."""
        with self.lock:
            for item in self.data:
                if item['id'] == item_id:
                    return item
            return None

    def create_item(self, name, done):
        """Creates a new item in the data store."""
        global next_id
        with self.lock:
            if not isinstance(name, str) or not isinstance(done, bool):
                raise ValueError("Invalid input type")

            item = {
                'id': next_id,
                'name': name,
                'done': done
            }
            self.data.append(item)
            next_id += 1
            return item

# Serial Communication Class
class SerialCommunicator:
    """
    Handles serial communication with the instrument.
    """
    def __init__(self):
        self.port = None
        self.lock = threading.Lock()

    def open(self, port, baudrate):
        """Opens the serial port."""
        with self.lock:
            try:
                self.port = serial.Serial(port, baudrate, timeout=1)  # 1 second timeout
                logging.info(f"Serial port {port} opened successfully.")
            except serial.SerialException as e:
                logging.error(f"Error opening serial port {port}: {e}")
                raise

    def close(self):
        """Closes the serial port."""
        with self.lock:
            if self.port and self.port.is_open:
                self.port.close()
                logging.info("Serial port closed.")

    def send(self, cmd):
        """Sends a command to the serial port."""
        with self.lock:
            if not self.port or not self.port.is_open:
                logging.error("Serial port is not open.")
                return False

            try:
                cmd = cmd.encode('utf-8')
                self.port.write(cmd)
                logging.debug(f"Sent command: {cmd.decode('utf-8')}")
                return True
            except serial.SerialException as e:
                logging.error(f"Error sending command: {e}")
                return False

    def receive_line(self):
        """Receives a line from the serial port."""
        with self.lock:
            if not self.port or not self.port.is_open:
                logging.error("Serial port is not open.")
                return None

            try:
                line = self.port.readline().decode('utf-8', errors='ignore').strip()
                logging.debug(f"Received line: {line}")
                return line
            except serial.SerialException as e:
                logging.error(f"Error receiving data: {e}")
                return None

    def __enter__(self):
        """Context manager entry."""
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        """Context manager exit, closes the port."""
        self.close()

# Initialize DataManager
data_manager = DataManager()

# Initialize SerialCommunicator
serial_communicator = SerialCommunicator()

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logging.info("Received shutdown signal. Cleaning up...")
    shutdown_flag.set()
    if serial_communicator:
        serial_communicator.close()
    sys.exit(0)

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

