def get_data():
    """Returns all data."""
    data = data_manager.get_all()
    return jsonify(data), 200

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    """Returns data by ID."""
    item = data_manager.get_by_id(item_id)
    if item:
        return jsonify(item), 200
    else:
        return Response("Item not found", status=404, mimetype='text/plain')

@app.route('/data', methods=['POST'])
def create_data():
    """Creates new data."""
    try:
        data = request.get_json()
        if not isinstance(data, dict):
            raise ValueError("Request body must be a JSON object")

        name = data.get('name')
        done = data.get('done')

        if not isinstance(name, str):
            raise ValueError("Name must be a string")
        if not isinstance(done, bool):
            raise ValueError("Done must be a boolean")

        item = data_manager.create_item(name, done)
        return jsonify(item), 201

    except (ValueError, json.JSONDecodeError) as e:
        logging.error(f"Error creating data: {e}")
        return Response(str(e), status=400, mimetype='text/plain')

@app.route('/version', methods=['GET'])
def get_instrument_version():
    """Queries the connected instrument for its version information."""
    global serial_communicator
    try:
        with serial_communicator:
            # Open the serial port (replace with your actual port and baud rate)
            serial_communicator.open('/dev/ttyUSB0', 9600)

            # Send the *IDN? command to query the instrument
            if not serial_communicator.send('*IDN?\n'):
                return Response("Failed to send command to instrument.", status=500, mimetype='text/plain')

            # Read the response from the instrument
            response = serial_communicator.receive_line()

            if response is None:
                return Response("Timeout waiting for instrument response.", status=504, mimetype='text/plain')

            return Response(response, mimetype='text/plain')

    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
        return Response(f"Serial communication error: {e}", status=502, mimetype='text/plain')
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        return Response(f"An unexpected error occurred: {e}", status=500, mimetype='text/plain')
    finally:
        if serial_communicator:
            serial_communicator.close()

def main():
    """Main function to start the Flask app."""
    logging.info("Starting Flask app...")
    try:
        app.run(host='0.0.0.0', port=5000, debug=False, use_reloader=False)  # Disable reloader for production
    except Exception as e:
        logging.error(f"Error starting Flask app: {e}")
    finally:
        logging.info("Flask app stopped.")

if __name__ == '__main__':
    main()

