def read_power_data():
    """Reads power consumption data from the serial port."""
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            logging.info("Serial port opened successfully.")
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        try:
                            power = float(line)
                            log_power_consumption(power)
                        except ValueError:
                            logging.warning(f"Invalid data received: {line}")
                except serial.SerialException as e:
                    logging.error(f"Serial communication error: {e}")
                    break  # Exit the loop if a serial error occurs
                except Exception as e:
                    logging.error(f"An unexpected error occurred: {e}")
                    break # Exit the loop on unexpected errors
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
    except Exception as e:
        logging.error(f"An error occurred during serial port initialization: {e}")

def log_power_consumption(power):
    """Logs the power consumption data to a file."""
    logging.info(f"Power: {power} W")

if __name__ == "__main__":
    try:
        read_power_data()
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    finally:
