from flask import Flask, Response, request, jsonify, abort
import serial
import time
import os

# Initialize the Flask application
app = Flask(__name__)

# In-memory data store for tasks (id, name, done)
tasks = [
    {'id': 1, 'name': 'Get Coffee', 'done': False},
    {'id': 2, 'name': 'Write Tutorial', 'done': False}
]


# Function to generate the next task ID
def get_next_id():
    """Generates the next available ID for a new task."""
    return max(task['id'] for task in tasks) + 1 if tasks else 1


# Route to get the instrument version
@app.route('/version')
def get_instrument_version():
    """Queries the connected instrument for its version information."""
    try:
        with serial.Serial('/dev/ttyUSB0', 9600, timeout=1) as ser:
            ser.write(b'*IDN?\n')
            time.sleep(0.1)  # Give the instrument time to respond
            response = ser.read_all().decode('utf-8')
            return Response(response, mimetype='text/html')
    except serial.SerialException as e:
        return Response(f"Error communicating with the instrument: {e}", status=503, mimetype='text/html')


# Route to get all tasks
@app.route('/getdata')
def get_all_tasks():
    """Returns all tasks in JSON format."""
    return jsonify(tasks)


# Route to get a specific task by ID
@app.route('/getset/<int:task_id>')
def get_task_by_id(task_id):
    """Returns a specific task by its ID."""
    task = next((task for task in tasks if task['id'] == task_id), None)
    if task:
        return jsonify(task)
    else:
        abort(404)


# Route to add a new task (GET method)
@app.route('/getpost/<int:task_id>/<name>')
def add_task_get(task_id, name):
    """Adds a new task using GET request parameters."""
    new_task = {
        'id': task_id,
        'name': name,
        'done': False
    }
    tasks.append(new_task)
    return jsonify(tasks)


# Route to add a new task (POST method with JSON data)
@app.route('/postjson', methods=['POST'])
def add_task_post_json():
    """Adds a new task using JSON data in the request body."""
    try:
        if 'application/json' in request.headers.get('Content-Type', ''):
            new_task = request.get_json()
        else:
            new_task = request.get_json(force=True)  # Try parsing even if not JSON content type

        new_task['id'] = get_next_id()
        tasks.append(new_task)
        return jsonify(tasks)
    except (TypeError, ValueError) as e:
        abort(400, description=f"Invalid JSON data: {e}")


# Route to add a new task (POST method with form-encoded data)
@app.route('/postjson', methods=['POST'])
def add_task_post_form():
    """Adds a new task using form-encoded data in the request body."""
    try:
        new_task = {
            'name': request.form['name'],
            'done': request.form.get('done', 'False').lower() == 'true'  # Handle 'done' as boolean string
        }
        new_task['id'] = get_next_id()
        tasks.append(new_task)
        return jsonify(tasks)
    except (KeyError, TypeError) as e:
        abort(400, description=f"Invalid form data: {e}")


# Main entry point
if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')

